import React, { useEffect, useState } from 'react';
import { getOrders, getProducts } from '../data/dataFetching';
import { useParams } from 'react-router-dom';
import { Timeline } from 'primereact/timeline';
import 'primereact/resources/themes/saga-blue/theme.css';  // Choose a theme
import 'primereact/resources/primereact.min.css';
import 'primeicons/primeicons.css';
import './orderDetails.css';

function OrderDetails() {

    const { id } = useParams();

    const [orders, setOrders] = useState([]);


    useEffect(() => {
        getOrders().then(data => setOrders(data.filter((item) => item.id == id)));
    }, []);


    const [products, setProducts] = useState([]);

    useEffect(() => {
        getProducts().then(data => setProducts(data));
    }, []);


    const events = [
        { status: 'Ordered' },
        { status: 'Picked' },
        { status: 'Shipped' },
        { status: 'Delivered' }
    ];

    const getStatusIndex = (status) => {
        switch (status) {
            case 'Ordered': return 0;
            case 'Picked': return 1;
            case 'Shipped': return 2;
            case 'Delivered': return 3;
            default: return -1;
        }
    };

    const currentStatusIndex = getStatusIndex(orders.status);

    return (
        <div className='order-details-container'>
            <div className='order-details-header'>

                <h1>Order number:</h1>

                {orders.map(orders => (
                    <h1 key={orders.id}>{orders.id}</h1>
                ))}

            </div>

            <div className='order-details-info'>

                <div className='order-date'>
                    <h5>Order date:</h5>
                    {orders.map(order => (
                        <p key={order.id}>{order.date}</p>
                    ))}
                </div>

                <div className='order-payment'>
                    <h5>Payment method:</h5>
                    {orders.map(order => (
                        <p key={order.id}>{order.payment}</p>
                    ))}
                </div>

                <div className='order-delivery'>
                    <h5>Delivery status:</h5>
                    {orders.map(order => (
                        <>
                            <Timeline className='timeline-container' value={events} layout="horizontal"
                                marker={(item, index) => (
                                    <i className={" " + index < getStatusIndex(order.status) ? "pi pi-circle-fill active-connector" : "pi pi-circle-fill inactive-connector"} style={{ color: index <= getStatusIndex(order.status) ? 'var(--highlight-color)' : 'var(--stroke-color)', fontSize: '2rem' }} />
                                )}
                                content={(item) => (
                                    <h6>{item.status}</h6>
                                )}
                            />
                        </>
                    ))}
                </div>


                <div className='order-details'>
                    <hr></hr>

                    <h4>Order details:</h4>

                    <table className='order-details-table'>
                        <tbody>
                            {products.length > 0 &&
                                products.map((item) => {
                                    return <>
                                    
                                        <tr >
                                            <td rowSpan={3}><span className={item.product_picture}></span></td>
                                            <td><h5>{item.name}</h5></td>
                                            <td rowSpan={3}>{item.price} kr</td>
                                        </tr>
                                        <tr>
                                            <td>Category: {item.category}</td>
                                        </tr>
                                        <tr>
                                            <td>Quantity: 1</td>
                                        </tr>
                                    </>

                                })
                            }
                        </tbody>

                    </table>

                    <hr></hr>

                    <h5 className='order-details-totalPrice'>Total price: {products.length > 0 && products.reduce(function(prev, cur) { return prev + cur.price }, 0)}</h5>



                </div>




            </div>


        </div>
    )
}

export default OrderDetails;
